const planBody = (slug, tail = '') => `"file_path":"[^"]*/tasks/${slug}/steps/plan-body\\.md"${tail === '' ? '' : `.*${tail}`}`;
const FIVE_FIELDS = 'Goal.*Changes.*Accept.*Checks.*Leaves out';
